use strict;
use warnings;
use File::Find;

my $ROOT = "/bench/repo";
my @TYPES = qw(
  Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare
  Reaction User UserIdentity UserSetting AuthenticationConfigState
  RowStatus Visibility Role InboxStatus MemoRelationType
);

sub is_store_layer {
  my $rel = $_[0];
  $rel =~ s|^$ROOT/||;
  return $rel =~ m{^store(/|$)};
}

my @outside;
find({
  wanted => sub {
    return unless -f && /\.go$/;
    return if $File::Find::name =~ m{/\.git/};
    return if is_store_layer($File::Find::name);
    push @outside, $File::Find::name;
  },
  no_chdir => 1,
}, $ROOT);

sub pkg_of {
  my $p = $_[0];
  $p =~ s{/[^/]+$}{};
  return $p;
}

print "Outside-layer Go files: ", scalar(@outside), "\n";
my %opkgs;
$opkgs{pkg_of($_)} = 1 for @outside;
print "Outside-layer packages: ", scalar(keys %opkgs), "\n";
print "\nOutside packages:\n";
print "  $_\n" for sort keys %opkgs;

my %results;
for my $t (@TYPES) {
  my %pkgs;
  my @files;
  my $pat = qr/store\.\Q$t\E\b/;
  for my $f (@outside) {
    open my $fh, "<", $f or next;
    local $/;
    my $text = <$fh>;
    close $fh;
    if ($text =~ $pat) {
      $pkgs{pkg_of($f)} = 1;
      push @files, $f;
    }
  }
  $results{$t} = [\%pkgs, \@files];
}

print "\n=== Entity type package counts (store.Type) ===\n";
for my $t (sort { scalar(keys %{$results{$b}[0]}) <=> scalar(keys %{$results{$a}[0]}) || $a cmp $b } @TYPES) {
  my ($pkgs, $files) = @{$results{$t}};
  printf "\n%s: %d packages, %d files\n", $t, scalar(keys %$pkgs), scalar(@$files);
  print "  - $_\n" for sort keys %$pkgs;
}
'

